"""Column-profiling scorecard.

Usage: python profile.py <csv_path> [--out profile.json]

Emits a JSON profile per column:
  - dtype_guess : one of int / float / date / str
  - null_rate   : fraction of rows that are null (blanks, '', 'N/A', ...)
  - null_count  : number of null cells
  - distinct_count : distinct non-null values
  - min / max   : for numeric columns (int, float)
  - top3        : [(value, count), ...] for string columns,
                  ordered by descending count, ties broken alphabetically
"""

from __future__ import annotations

import argparse
import csv
import json
import sys
from datetime import date

# Raw cell values treated as missing.
NULL_SENTINELS = {"", "n/a", "na", "null", "none"}


def is_null(raw: str | None) -> bool:
    return raw is None or raw.strip().lower() in NULL_SENTINELS


def _try_int(value: str) -> int | None:
    try:
        # Reject floats disguised as ints ("1.5") via strict parse.
        if "." in value or "e" in value.lower():
            return None
        return int(value)
    except ValueError:
        return None


def _try_float(value: str) -> float | None:
    try:
        return float(value)
    except ValueError:
        return None


def _try_date(value: str) -> date | None:
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


def guess_dtype(values: list[str]) -> str:
    """Guess the dtype of a list of non-null raw string values."""
    if not values:
        return "str"
    if all(_try_int(v) is not None for v in values):
        return "int"
    if all(_try_float(v) is not None for v in values):
        return "float"
    if all(_try_date(v) is not None for v in values):
        return "date"
    return "str"


def profile_column(name: str, raw_values: list[str]) -> dict:
    n_rows = len(raw_values)
    non_null = [v.strip() for v in raw_values if not is_null(v)]
    null_count = n_rows - len(non_null)

    dtype = guess_dtype(non_null)

    profile: dict = {
        "dtype_guess": dtype,
        "null_count": null_count,
        "null_rate": null_count / n_rows if n_rows else 0.0,
        "distinct_count": len(set(non_null)),
    }

    if dtype == "int":
        nums = [_try_int(v) for v in non_null]
        profile["min"] = min(nums)
        profile["max"] = max(nums)
    elif dtype == "float":
        nums = [_try_float(v) for v in non_null]
        profile["min"] = min(nums)
        profile["max"] = max(nums)
    elif dtype == "date":
        dates = [_try_date(v) for v in non_null]
        profile["min"] = min(dates).isoformat()
        profile["max"] = max(dates).isoformat()
    else:  # str: top-3 by count, ties broken alphabetically
        counts: dict[str, int] = {}
        for v in non_null:
            counts[v] = counts.get(v, 0) + 1
        ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
        profile["top3"] = [[value, count] for value, count in ranked[:3]]

    return profile


def profile_csv(path: str) -> dict[str, dict]:
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.reader(fh)
        header = next(reader)
        columns: list[list[str]] = [[] for _ in header]
        for row in reader:
            for i, cell in enumerate(row):
                columns[i].append(cell)
    return {name: profile_column(name, cols) for name, cols in zip(header, columns)}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Column profiling scorecard")
    parser.add_argument("csv_path", help="Path to the input CSV")
    parser.add_argument("--out", default=None, help="Output JSON path (default: alongside CSV)")
    args = parser.parse_args(argv)

    profiles = profile_csv(args.csv_path)
    out_path = args.out or args.csv_path.rsplit(".", 1)[0] + ".profile.json"
    with open(out_path, "w", encoding="utf-8") as fh:
        json.dump(profiles, fh, indent=2, sort_keys=True)
    print(f"wrote {out_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

